-- UNIBUD identity access control and account isolation
-- PostgreSQL 16+. Apply after 0001_identity_foundation.sql.
-- Runtime account context is accepted only when accompanied by a valid,
-- short-lived HMAC generated by the trusted server after session validation.
-- A caller may SET arbitrary GUC values; RLS never trusts them without HMAC.

BEGIN;

DO $roles$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'unibud_migrator') THEN
    CREATE ROLE unibud_migrator NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOINHERIT;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'unibud_app') THEN
    CREATE ROLE unibud_app NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOINHERIT;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'unibud_readonly') THEN
    CREATE ROLE unibud_readonly NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOINHERIT;
  END IF;
END;
$roles$;

CREATE EXTENSION IF NOT EXISTS pgcrypto;

CREATE SCHEMA IF NOT EXISTS unibud_private;
REVOKE ALL ON SCHEMA unibud_private FROM PUBLIC;
GRANT USAGE ON SCHEMA unibud_private TO unibud_app, unibud_readonly;

-- Provision a random 32-byte key out-of-band per environment. The application
-- signer and database verifier receive the same secret through separate
-- secret-manager bindings. Never commit or seed a production key in a migration.
CREATE TABLE IF NOT EXISTS unibud_private.context_signing_keys (
  key_id TEXT PRIMARY KEY,
  secret BYTEA NOT NULL CHECK (octet_length(secret) >= 32),
  active BOOLEAN NOT NULL DEFAULT true,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX context_signing_keys_one_active_idx
  ON unibud_private.context_signing_keys(active) WHERE active;
REVOKE ALL ON unibud_private.context_signing_keys FROM PUBLIC, unibud_app, unibud_readonly, unibud_migrator;

CREATE OR REPLACE FUNCTION unibud_private.current_account_id()
RETURNS UUID
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, public, unibud_private
AS $function$
DECLARE
  v_account TEXT;
  v_expiry TEXT;
  v_nonce TEXT;
  v_signature TEXT;
  v_key BYTEA;
  v_expected BYTEA;
  v_supplied BYTEA;
  v_diff INTEGER := 0;
  v_index INTEGER;
  v_now BIGINT;
BEGIN
  v_account := current_setting('unibud.account_id', true);
  v_expiry := current_setting('unibud.context_expiry', true);
  v_nonce := current_setting('unibud.context_nonce', true);
  v_signature := current_setting('unibud.context_signature', true);

  IF v_account IS NULL OR v_expiry IS NULL OR v_nonce IS NULL OR v_signature IS NULL
     OR v_nonce !~ '^[0-9a-fA-F-]{36}$'
     OR v_signature !~ '^[0-9a-f]{64}$'
     OR v_expiry !~ '^[0-9]{1,12}$'
     OR v_account !~ '^[0-9a-fA-F-]{36}$' THEN
    RETURN NULL;
  END IF;

  v_now := floor(extract(epoch FROM statement_timestamp()))::BIGINT;
  IF v_expiry::BIGINT < v_now OR v_expiry::BIGINT > v_now + 120 THEN
    RETURN NULL;
  END IF;

  SELECT secret INTO v_key
  FROM unibud_private.context_signing_keys
  WHERE active
  ORDER BY created_at DESC
  LIMIT 1;

  IF v_key IS NULL THEN
    RETURN NULL;
  END IF;

  v_expected := public.hmac(
    convert_to(v_account || ':' || v_expiry || ':' || v_nonce, 'UTF8'),
    v_key,
    'sha256'
  );
  v_supplied := decode(v_signature, 'hex');
  IF octet_length(v_supplied) <> 32 THEN
    RETURN NULL;
  END IF;

  -- Fixed-length XOR accumulation avoids a first-differing-byte comparison.
  FOR v_index IN 0..31 LOOP
    v_diff := v_diff | (get_byte(v_expected, v_index) # get_byte(v_supplied, v_index));
  END LOOP;
  IF v_diff <> 0 THEN
    RETURN NULL;
  END IF;

  RETURN v_account::UUID;
EXCEPTION WHEN OTHERS THEN
  -- Invalid/malformed context fails closed. Do not leak parsing or key details.
  RETURN NULL;
END;
$function$;

REVOKE ALL ON FUNCTION unibud_private.current_account_id() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION unibud_private.current_account_id() TO unibud_app, unibud_readonly;

-- FORCE RLS ensures table owners are subject to policies too (superusers and
-- BYPASSRLS roles remain privileged and must never be used by application code).
ALTER TABLE accounts ENABLE ROW LEVEL SECURITY;
ALTER TABLE accounts FORCE ROW LEVEL SECURITY;
CREATE POLICY accounts_account_isolation ON accounts
  USING (id = unibud_private.current_account_id())
  WITH CHECK (id = unibud_private.current_account_id());

ALTER TABLE authentication_identities ENABLE ROW LEVEL SECURITY;
ALTER TABLE authentication_identities FORCE ROW LEVEL SECURITY;
CREATE POLICY authentication_identities_account_isolation ON authentication_identities
  USING (account_id = unibud_private.current_account_id())
  WITH CHECK (account_id = unibud_private.current_account_id());

ALTER TABLE account_sessions ENABLE ROW LEVEL SECURITY;
ALTER TABLE account_sessions FORCE ROW LEVEL SECURITY;
CREATE POLICY account_sessions_account_isolation ON account_sessions
  USING (account_id = unibud_private.current_account_id())
  WITH CHECK (account_id = unibud_private.current_account_id());

ALTER TABLE profiles ENABLE ROW LEVEL SECURITY;
ALTER TABLE profiles FORCE ROW LEVEL SECURITY;
CREATE POLICY profiles_account_isolation ON profiles
  USING (
    owner_account_id = unibud_private.current_account_id()
    OR EXISTS (
      SELECT 1 FROM profile_memberships membership
      WHERE membership.profile_id = profiles.id
        AND membership.account_id = unibud_private.current_account_id()
        AND membership.status = 'active'
    )
  )
  WITH CHECK (owner_account_id = unibud_private.current_account_id());

ALTER TABLE profile_memberships ENABLE ROW LEVEL SECURITY;
ALTER TABLE profile_memberships FORCE ROW LEVEL SECURITY;
CREATE POLICY profile_memberships_account_isolation ON profile_memberships
  USING (
    account_id = unibud_private.current_account_id()
    OR owner_account_id = unibud_private.current_account_id()
  )
  WITH CHECK (
    account_id = unibud_private.current_account_id()
    OR owner_account_id = unibud_private.current_account_id()
  );

ALTER TABLE resource_grants ENABLE ROW LEVEL SECURITY;
ALTER TABLE resource_grants FORCE ROW LEVEL SECURITY;
CREATE POLICY resource_grants_account_isolation ON resource_grants
  USING (
    subject_account_id = unibud_private.current_account_id()
    OR issuer_account_id = unibud_private.current_account_id()
  )
  WITH CHECK (
    subject_account_id = unibud_private.current_account_id()
    OR issuer_account_id = unibud_private.current_account_id()
  );

ALTER TABLE security_audit_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE security_audit_events FORCE ROW LEVEL SECURITY;
CREATE POLICY security_audit_events_account_isolation ON security_audit_events
  USING (actor_account_id = unibud_private.current_account_id())
  WITH CHECK (actor_account_id = unibud_private.current_account_id());

-- Runtime is a NOLOGIN group role. Provision a distinct LOGIN role per service
-- outside migrations and grant it only the group role(s) it needs.
GRANT SELECT, INSERT, UPDATE ON
  accounts, authentication_identities, account_sessions, profiles,
  profile_memberships, resource_grants
TO unibud_app;
GRANT SELECT, INSERT ON security_audit_events TO unibud_app;
GRANT SELECT ON
  accounts, profiles, profile_memberships, resource_grants
TO unibud_readonly;

-- No application DELETE, TRUNCATE, schema creation, ownership or bypass rights.
REVOKE DELETE, TRUNCATE, REFERENCES, TRIGGER ON
  accounts, authentication_identities, account_sessions, profiles,
  profile_memberships, resource_grants, security_audit_events
FROM unibud_app, unibud_readonly;

COMMENT ON FUNCTION unibud_private.current_account_id() IS
  'Returns the account only when short-lived transaction context has a valid HMAC; arbitrary GUC values fail closed.';
COMMENT ON TABLE unibud_private.context_signing_keys IS
  'Private HMAC verification key material; provision via secret management and never expose to runtime SQL roles.';

COMMIT;
